// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output `generated`, whether decoding is
// currently inside a visible constrained SMILES span, and the active span
// contents `currentConstrainedOut`. Outside the span it uses short free-LM
// chunking so that ordinary prompt text can be produced naturally until either
// EOS or the visible opener "<<" is observed. Inside the span it switches to
// parser-controlled decoding, using the parser-validity count to choose between
// a one-token adaptive constrained step in narrow states and a bounded
// multi-token constrained-symbol step in wider states.
// 
// The main observations are: whether we are already inside a constrained span,
// whether the parser reports the current constrained prefix complete, whether
// unconstrained chunking naturally emitted the open delimiter, and how many
// valid next tokens the parser currently allows. These observations let the
// strategy keep SMILES generation parser-valid at every committed constrained
// update while still allowing efficient free generation outside the span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Outside-span chunk branch: if no opener is observed, `insideConstrainedOut`
//   stays false, so the implication is vacuous. If `UnconstrainedChunk` stops on
//   the already-emitted opener "<<", we transition with
//   `EnterObservedConstrainedSpan`, which sets `currentConstrainedOut := []`;
//   this is parser-valid by the method precondition `parser.IsValidPrefix([])`.
// - Complete-prefix close branch: `CloseConstrainedSpan` exits constrained mode,
//   so `insideConstrainedOut` becomes false and the implication is vacuous.
// - Narrow constrained branch: `AdaptiveConstrainedStep` returns either EOS or a
//   parser-valid next token. On EOS we break without changing the constrained
//   state; otherwise `AppendConstrainedToken` commits that valid token, so the
//   new `currentConstrainedOut` remains a valid parser prefix.
// - Wide constrained-symbol branch: `ConstrainedSymbolInGenerated` returns a
//   `currentOut` that is the longest accepted parser-valid prefix of the sampled
//   chunk, so assigning `currentConstrainedOut := symbolOut` preserves parser
//   validity directly.
//
// progress:
// - Outside-span chunk branch: `steps` increases by `stepsUsed`, and
//   `UnconstrainedChunk` extends visible output by at most those consumed token
//   steps; EOS, if hit, counts in `stepsUsed` without being appended, so
//   `|generated| <= |generatedPrefix| + steps` is preserved.
// - Complete-prefix close branch: `CloseConstrainedSpan` consumes one token-step
//   for the closing delimiter and appends at most that one visible token, so the
//   bound is preserved when `steps := steps + 1`.
// - Narrow constrained branch: `AdaptiveConstrainedStep` consumes one token-step;
//   if it returns EOS, no visible token is appended, otherwise exactly one token
//   is appended by `AppendConstrainedToken`. Thus visible growth is at most the
//   one-step increase.
// - Wide constrained-symbol branch: `ConstrainedSymbolInGenerated` consumes
//   `stepsUsed` token-steps and may accept only a prefix of the sampled chunk;
//   rejected suffix tokens or EOS still count in `stepsUsed`, so visible growth
//   is at most `stepsUsed`, preserving the invariant.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := maxSteps - steps;
    var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedGenerated;
    steps := steps + stepsUsed;
    if stoppedOnEos {
      break;
    } else if stoppedOnOpenSpan {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    if validCount <= narrowThreshold {
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget == 0 || stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolCurrent, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      currentConstrainedOut := symbolCurrent;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

