// CSD_RATIONALE_BEGIN
// The measured failure source is total absence of extracted outputs, with both
// prior families spending effort on outside-span behavior even though this task
// only needs a constrained SMILES answer. Because repeated outside/opening-shape
// changes produced no movement, this revision makes a structural simplification:
// always ensure we are inside a visible constrained span immediately, then stay
// there until either the parser reports a complete SMILES and we close once, or
// budget ends.
//
// To preserve the only evidence-backed ingredient from prior attempts, the
// strategy still closes immediately on parser-complete prefixes. The changed
// causal axis is the inside-span decoder: instead of symbol-chunking plus a
// narrowness switch, it uses a single token-level constrained policy throughout.
// Early in the span it uses `ConfidenceGatedStep` to let an already-valid LM
// preference pass through while still falling back to hard parser control; once
// the span has some content it switches to `SafeRepetitionPenaltyStep` to reduce
// trivial loops and encourage fuller valid SMILES strings. This removes the
// previous mixed control path and focuses all budget on producing one complete
// visible constrained answer.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Immediate-open / observed-entry branch: if we start outside, either
//   `OpenConstrainedSpan` or `EnterObservedConstrainedSpan` sets
//   `insideConstrainedOut := true` and `currentConstrainedOut := []`; the
//   precondition gives `parser.IsValidPrefix([])`, so the invariant holds.
// - Complete-prefix close branch: `CloseConstrainedSpan` exits constrained mode
//   and clears the active constrained content, so the implication
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)` is
//   vacuous afterward.
// - Early-span token branch via `ConfidenceGatedStep`: the helper returns EOS or
//   a token whose extension preserves parser validity; on EOS we break without
//   changing constrained state, otherwise `AppendConstrainedToken` commits that
//   valid token and preserves parser validity.
// - Later-span token branch via `SafeRepetitionPenaltyStep`: similarly, the
//   helper returns EOS or a parser-valid next token; appending the non-EOS token
//   preserves `parser.IsValidPrefix(currentConstrainedOut)`.
//
// progress:
// - Immediate-open branch with `OpenConstrainedSpan`: this consumes exactly one
//   token-step and appends at most the visible opener token, so after
//   `steps := steps + 1` the bound `|generated| <= |generatedPrefix| + steps`
//   is preserved.
// - Observed-entry branch with `EnterObservedConstrainedSpan`: this consumes no
//   token budget and does not change visible output, so the same bound is
//   preserved with `steps` unchanged.
// - Complete-prefix close branch: `CloseConstrainedSpan` consumes one token-step
//   and appends at most the visible closer token, so increasing `steps` by 1
//   preserves the linear output-length bound.
// - Each constrained token branch consumes one token-step. If EOS is returned,
//   visible output does not grow; otherwise `AppendConstrainedToken` appends
//   exactly one visible token. Thus visible growth is at most the consumed
//   budget in either branch, preserving `|generated| <= |generatedPrefix| + steps`.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var openedHere: bool := false;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if |generated| >= 1 && generated[|generated| - 1] == "<<" {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
      openedHere := true;
    } else {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      openedHere := true;
      steps := steps + 1;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
